// Package attack knows Enterprise ATT&CK's techniques and tactics offline, so
// lrng can name a finding's technique, place it under the right tactics, and
// carry IDs MITRE has since revoked over to their replacements.
//
// The bundled table (data/enterprise.tsv) is generated by cmd/attackgen from
// MITRE's published STIX bundle. It keeps, per technique ID, its name, its
// tactics and whether it is active, revoked (and by what) or deprecated, plus
// the tactics in matrix order. ATT&CK v19 (April 2026) is why this matters:
// it retired Defense Evasion, split it into Stealth and Defense Impairment,
// and revoked T1562 and its sub-techniques into new IDs, so reports written
// by earlier lrng versions name techniques today's Navigator no longer shows.
//
// ATT&CK is © The MITRE Corporation, reproduced and distributed with its
// permission; see data/LICENSE.attack and THIRD_PARTY_NOTICES.md.
package attack

import (
	"bufio"
	"bytes"
	_ "embed"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"sync"
)

//go:embed data/enterprise.tsv
var embedded []byte

// Status says whether a technique ID is current.
type Status uint8

const (
	Active     Status = 1
	Revoked    Status = 2 // replaced: see Technique.RevokedBy
	Deprecated Status = 3 // withdrawn with no replacement
)

func (s Status) String() string {
	switch s {
	case Active:
		return "active"
	case Revoked:
		return "revoked"
	case Deprecated:
		return "deprecated"
	}
	return "unknown"
}

// Tactic is one column of the Enterprise matrix.
type Tactic struct {
	ID        string // "TA0005"
	ShortName string // "stealth", the name STIX and Navigator use
	Name      string // "Stealth"
}

// Technique is one technique or sub-technique ID.
type Technique struct {
	ID        string
	Name      string
	Status    Status
	RevokedBy string   // the replacing ID, for a revoked technique ("" if MITRE named none)
	Tactics   []string // tactic short names, in matrix order (empty unless active)
}

// Table is a loaded technique table.
type Table struct {
	Version   string // ATT&CK version, e.g. "20.1"
	Source    string
	Generated string
	Tactics   []Tactic
	tech      map[string]Technique
}

// IDRe matches a technique or sub-technique ID.
var IDRe = regexp.MustCompile(`^T\d{4}(\.\d{3})?$`)

var tacticRe = regexp.MustCompile(`^TA\d{4}$`)

var (
	once   sync.Once
	loaded *Table
	errLd  error
)

// Bundled returns the table embedded in the binary. It is parsed once.
func Bundled() (*Table, error) {
	once.Do(func() { loaded, errLd = Parse(embedded) })
	return loaded, errLd
}

// Parse reads a table in the format cmd/attackgen writes.
func Parse(data []byte) (*Table, error) {
	t := &Table{tech: map[string]Technique{}}
	shorts := map[string]bool{}
	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 64<<10), 1<<20)
	for n := 1; sc.Scan(); n++ {
		line := sc.Text()
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "#") {
			if k, v, ok := strings.Cut(strings.TrimSpace(line[1:]), ":"); ok {
				switch strings.TrimSpace(k) {
				case "source":
					t.Source = strings.TrimSpace(v)
				case "attack_version":
					t.Version = strings.TrimSpace(v)
				case "generated":
					t.Generated = strings.TrimSpace(v)
				}
			}
			continue
		}
		f := strings.Split(line, "\t")
		bad := func(why string) error { return fmt.Errorf("attack: line %d: %s", n, why) }
		switch f[0] {
		case "tactic":
			if len(f) != 4 || !tacticRe.MatchString(f[1]) || f[2] == "" || f[3] == "" {
				return nil, bad("a tactic line needs an ID, a short name and a name")
			}
			if shorts[f[2]] {
				return nil, bad("duplicate tactic " + f[2])
			}
			shorts[f[2]] = true
			t.Tactics = append(t.Tactics, Tactic{ID: f[1], ShortName: f[2], Name: f[3]})
		case "tech":
			if len(f) != 6 {
				return nil, bad("a technique line needs 6 fields")
			}
			tc := Technique{ID: f[1], RevokedBy: dash(f[3]), Name: f[5]}
			if !IDRe.MatchString(tc.ID) {
				return nil, bad("bad technique ID " + f[1])
			}
			if _, dup := t.tech[tc.ID]; dup {
				return nil, bad("duplicate technique " + tc.ID)
			}
			switch f[2] {
			case "active":
				tc.Status = Active
			case "revoked":
				tc.Status = Revoked
			case "deprecated":
				tc.Status = Deprecated
			default:
				return nil, bad("unknown status " + f[2])
			}
			if tc.RevokedBy != "" && (tc.Status != Revoked || !IDRe.MatchString(tc.RevokedBy)) {
				return nil, bad("only a revoked technique names a valid replacement")
			}
			if ts := dash(f[4]); ts != "" {
				tc.Tactics = strings.Split(ts, ",")
				for _, s := range tc.Tactics {
					if !shorts[s] {
						return nil, bad("unknown tactic " + s + " (tactic lines come first)")
					}
				}
			}
			if tc.Status == Active && len(tc.Tactics) == 0 {
				return nil, bad("an active technique needs a tactic")
			}
			t.tech[tc.ID] = tc
		default:
			return nil, bad("unknown record type " + f[0])
		}
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	if t.Version == "" || len(t.Tactics) == 0 || len(t.tech) == 0 {
		return nil, fmt.Errorf("attack: table needs an attack_version, tactics and techniques")
	}
	for id, tc := range t.tech {
		if tc.RevokedBy != "" {
			if _, ok := t.tech[tc.RevokedBy]; !ok {
				return nil, fmt.Errorf("attack: %s is revoked by %s, which the table doesn't have", id, tc.RevokedBy)
			}
		}
	}
	return t, nil
}

func dash(s string) string {
	if s == "-" {
		return ""
	}
	return s
}

// Lookup returns a technique by ID.
func (t *Table) Lookup(id string) (Technique, bool) {
	tc, ok := t.tech[id]
	return tc, ok
}

// Len is the number of technique IDs in the table, current or not.
func (t *Table) Len() int { return len(t.tech) }

// IDs returns every technique ID in the table, sorted.
func (t *Table) IDs() []string {
	ids := make([]string, 0, len(t.tech))
	for id := range t.tech {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// Resolution is where an ID lands in the current matrix.
type Resolution struct {
	ID     string // the ID to use now ("" when Status is Unknown or a revocation has no successor)
	From   string // the ID asked about
	Status Status // Active, Revoked (ID is the successor), Deprecated, or 0 when unknown
	Name   string // the name of ID (or of From when deprecated)
}

// Remapped reports whether the ID changed.
func (r Resolution) Remapped() bool { return r.ID != "" && r.ID != r.From }

// Resolve follows revocations to a current ID. A deprecated technique is
// returned as itself, flagged; an ID the table doesn't know resolves to no ID.
func (t *Table) Resolve(id string) Resolution {
	r := Resolution{From: id}
	tc, ok := t.tech[id]
	if !ok {
		return r
	}
	r.Status = tc.Status
	for hops := 0; tc.Status == Revoked; hops++ {
		next, ok := t.tech[tc.RevokedBy]
		if tc.RevokedBy == "" || !ok || hops > 8 {
			r.Name = tc.Name
			return r // revoked with no usable successor
		}
		tc = next
	}
	if tc.Status == Deprecated && r.Status == Revoked {
		r.Status = Deprecated // revoked into something since withdrawn
	}
	r.ID, r.Name = tc.ID, tc.Name
	return r
}

// TacticsOf returns a current technique's tactic short names, or for a
// sub-technique with none of its own, its parent's.
func (t *Table) TacticsOf(id string) []string {
	if tc, ok := t.tech[id]; ok && len(tc.Tactics) > 0 {
		return tc.Tactics
	}
	if parent, _, ok := strings.Cut(id, "."); ok {
		if tc, ok := t.tech[parent]; ok {
			return tc.Tactics
		}
	}
	return nil
}
